layer.css:
[data-ryt="footer"] { color: var(--ryt-accent); background-color: rgb(240, 242, 249); border-top: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-radius: 12px; transition: border-color 0.15s, transform 0.15s }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.55; letter-spacing: -0.36px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3.6px; transition: color 0.15s }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.55; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 2.8px; padding-top: 8px; padding-right: 12px; padding-bottom: 8px; padding-left: 12px; transition: background-color 0.15s, color 0.15s }
[data-ryt="header"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-top: none }
[data-ryt="button"] { color: var(--ryt-accent); background-color: var(--ryt-surface); border-top: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-text) 10%, transparent); border-radius: 9999px; font-family: Arial; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 12px; padding-bottom: 4px; padding-left: 12px; transition: border-color 0.15s, color 0.15s; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: -0.36px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"]::after { content: ""; display: block; position: absolute; width: 100%; height: 23.1875px; color: var(--ryt-accent); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-top: 2px solid rgb(8, 145, 178); border-right: 2px solid rgb(8, 145, 178); border-bottom: 2px solid rgb(8, 145, 178); border-left: 2px solid rgb(8, 145, 178); border-radius: 9999px; font-family: Arial; font-size: 12px; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-accent); top: -1px; left: -1px }
[data-ryt="nav"] a:hover { color: #0e7490; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: #f7f8fb; color: #0b1020; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { color: #0e7490; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #0891b2; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; transform: translateY(-2px) }
